function officeWalletContribution(bill){const paid=Number(bill.paid_amount||0),grand=Number(bill.total_amount||0),government=Number(bill.gov_fee_total||0),service=Math.round((Number(bill.subtotal||0)-government)*100)/100,isCredit=String(bill.payment_mode||bill.mode||'')==='Credit';if(isCredit)return 0;if(Math.abs(paid-grand)<0.005)return service;if(Math.abs(paid-government)<0.005)return 0;if(paid>government)return Math.round((paid-government)*100)/100;if(paid>=1&&paid<government)return -Math.round((grand-service-paid)*100)/100;if(paid<1)return -government;return 0}
async function officeClients(){let rows=await api('office-clients'),editing=null,query='';const safe=v=>esc(v==null?'':String(v));const renderRows=()=>{const body=$('#office-client-rows'),q=query.trim().toLowerCase(),matches=rows.filter(x=>[x.company_name,x.owner_rep_name,x.mobile,x.labour_no,x.immigration_no,x.uae_pass_no].join(' ').toLowerCase().includes(q));body.innerHTML=matches.length?matches.map(x=>'<tr><td><b>'+safe(x.company_name)+'</b></td><td>'+safe(x.owner_rep_name||'—')+'</td><td>'+safe(x.mobile||'—')+'</td><td>'+safe(x.labour_no||'—')+'</td><td>'+safe(x.immigration_no||'—')+'</td><td>'+safe(x.uae_pass_no||'—')+'</td><td class="office-client-row-actions"><button type="button" class="office-icon-button" title="Edit" aria-label="Edit '+safe(x.company_name)+'" data-office-edit="'+x.id+'">✎</button><button type="button" class="office-icon-button office-delete-button" title="Delete" aria-label="Delete '+safe(x.company_name)+'" data-office-delete="'+x.id+'">×</button></td></tr>').join(''):'<tr><td colspan="7" class="office-client-empty">No matching Office clients.</td></tr>';document.querySelectorAll('[data-office-edit]').forEach(b=>b.onclick=()=>{editing=rows.find(x=>String(x.id)===b.dataset.officeEdit);draw();$('#office-client-form').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-office-delete]').forEach(b=>b.onclick=async()=>{const x=rows.find(r=>String(r.id)===b.dataset.officeDelete);if(!x||!window.confirm('Delete '+x.company_name+' from the Office client directory?'))return;try{await api('office-client-delete',{method:'POST',body:{id:x.id}});toast('Client deleted.');rows=await api('office-clients');renderRows()}catch(error){toast(error.message,true)}})};const draw=()=>{$('#content').innerHTML='<section class="office-page-heading"><span class="eyebrow">OFFICE · CLIENT REGISTER</span><h2>Client</h2><p>Save company and representative identification details for this Office workspace.</p></section><div class="office-client-layout"><form id="office-client-form" class="office-client-form"><input type="hidden" name="id" value="'+(editing?.id||'')+'"><div class="office-client-form-heading"><div><span class="eyebrow">CLIENT DETAILS</span><h3>'+(editing?'Edit client':'Add client')+'</h3></div>'+(editing?'<span class="office-edit-badge">Editing</span>':'')+'</div><div class="office-client-fields"><label>Company Name<input name="company_name" value="'+safe(editing?.company_name)+'" maxlength="180" autocapitalize="words" style="text-transform:capitalize" required></label><label>Owner / Rep. Name<div class="office-owner-combo"><input id="office-owner-input" name="owner_rep_name" value="'+safe(editing?.owner_rep_name)+'" maxlength="180" autocomplete="off" placeholder="Type or choose a saved name"><button type="button" class="office-owner-toggle" id="office-owner-toggle" aria-label="Show saved owner names" title="Show saved names">▾</button><div id="office-owner-suggestions" class="office-owner-suggestions office-applicant-suggestions" hidden></div></div></label><label>Mobile<input name="mobile" type="tel" value="'+safe(editing?.mobile)+'" maxlength="60"></label><label>Lbr No.<input name="labour_no" value="'+safe(editing?.labour_no)+'" maxlength="100"></label><label>Imm. No.<input name="immigration_no" value="'+safe(editing?.immigration_no)+'" maxlength="100"></label><label>UAE Pass No.<input name="uae_pass_no" value="'+safe(editing?.uae_pass_no)+'" maxlength="100"></label></div><div class="office-client-actions">'+(editing?'<button type="button" class="button button-outline" id="office-client-cancel">Cancel</button>':'')+'<button class="button button-dark">'+(editing?'Save changes':'Save client')+' <span>→</span></button></div></form><section class="office-client-register"><div class="office-client-register-head"><div><span class="eyebrow">SAVED OFFICE CLIENTS</span><h3>Client directory</h3></div><span class="office-client-count">'+rows.length+'</span></div><div class="office-client-search"><input id="office-client-search" type="search" placeholder="Search company, representative, mobile or ID" value="'+safe(query)+'"></div><div class="office-client-table-wrap"><table class="office-client-table"><thead><tr><th>Company Name</th><th>Owner / Rep. Name</th><th>Mobile</th><th>Lbr No.</th><th>Imm. No.</th><th>UAE Pass No.</th><th>Actions</th></tr></thead><tbody id="office-client-rows"></tbody></table></div></section></div>';renderRows();const ownerInput=$('#office-owner-input'),ownerList=$('#office-owner-suggestions');let ownerActive=-1;const showOwnerSuggestions=()=>{let q=ownerInput.value.trim().toLowerCase(),names=[...new Set(rows.map(x=>String(x.owner_rep_name||'').trim()).filter(Boolean))].filter(name=>!q||name.toLowerCase().includes(q));ownerActive=-1;ownerList.innerHTML=names.length?names.map(name=>'<button type="button" class="office-owner-option">'+safe(name)+'</button>').join(''):'<span class="office-owner-no-match">No saved match · keep typing to add a new name</span>';ownerList.hidden=false;ownerList.querySelectorAll('.office-owner-option').forEach(option=>{option.onmousedown=e=>e.preventDefault();option.onclick=()=>{ownerInput.value=option.textContent;ownerList.hidden=true;ownerActive=-1}})};ownerInput.onfocus=showOwnerSuggestions;ownerInput.oninput=showOwnerSuggestions;ownerInput.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){if(ownerList.hidden)showOwnerSuggestions();const options=[...ownerList.querySelectorAll('.office-owner-option')];if(!options.length)return;e.preventDefault();ownerActive=ownerActive<0?(e.key==='ArrowDown'?0:options.length-1):(ownerActive+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((option,index)=>{option.classList.toggle('active',index===ownerActive);option.setAttribute('aria-selected',index===ownerActive?'true':'false')});options[ownerActive].scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&!ownerList.hidden&&ownerActive>=0){e.preventDefault();ownerList.querySelectorAll('.office-owner-option')[ownerActive]?.click()}else if(e.key==='Escape'){ownerList.hidden=true;ownerActive=-1}};ownerInput.onblur=()=>setTimeout(()=>{ownerList.hidden=true;ownerActive=-1},160);const ownerToggle=$('#office-owner-toggle');ownerToggle.onmousedown=e=>e.preventDefault();ownerToggle.onclick=()=>{if(ownerList.hidden){showOwnerSuggestions();ownerInput.focus()}else ownerList.hidden=true};$('#office-client-search').oninput=e=>{query=e.target.value;renderRows()};const cancel=$('#office-client-cancel');if(cancel)cancel.onclick=()=>{editing=null;draw()};$('#office-client-form').onsubmit=async e=>{e.preventDefault();const companyName=e.currentTarget.elements.company_name;companyName.value=companyName.value.trim().replace(/(^|[\s-])([a-z])/g,(_,space,letter)=>space+letter.toUpperCase());try{await api('office-client-save',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});toast(editing?'Client updated.':'Client saved.');rows=await api('office-clients');editing=null;query='';draw()}catch(error){toast(error.message,true)}}};draw()}

